contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 1000000000000000000); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(uint256 amount) public {
        require(c.currentBetLimit() != amount);

        c.AdjustBetAmounts(amount); if (__ESBMC_reverted()) return;

        assert(c.currentBetLimit() == amount);
    }
}

